CREATE TABLE "DemoCoach" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "specialty" TEXT NOT NULL);
CREATE TABLE "DemoMember" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "status" TEXT NOT NULL, "coachId" TEXT NOT NULL REFERENCES "DemoCoach"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "DemoPlan" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "status" TEXT NOT NULL, "memberId" TEXT NOT NULL REFERENCES "DemoMember"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "DemoAppointment" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL, "memberId" TEXT NOT NULL REFERENCES "DemoMember"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "DemoProduct" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "kind" TEXT NOT NULL, "priceToman" INTEGER NOT NULL CHECK ("priceToman" >= 0));
